100	macro_rules! world_impl {
101	    ($W:ident for $ptr:ty) => {
102	        impl<$W: World> World for $ptr {
103	            fn library(&self) -> &LazyHash<Library> {
104	                self.deref().library()
105	            }
106	
107	            fn book(&self) -> &LazyHash<FontBook> {
108	                self.deref().book()
109	            }
