237	/// A selection of in-development features that should be enabled.
238	///
239	/// Can be collected from an iterator of [`Feature`]s.
240	#[derive(Debug, Default, Clone, Hash)]
241	pub struct Features(SmallBitSet);
242	
243	impl Features {
