260	impl FromIterator<Feature> for Features {
261	    fn from_iter<T: IntoIterator<Item = Feature>>(iter: T) -> Self {
262	        let mut set = SmallBitSet::default();
263	        for feature in iter {
264	            set.insert(feature as usize);
265	        }
266	        Self(set)
267	    }
268	}
